from scipy.optimize import least_squares
def design(pr):
    p,q,r,s=pr
    return np.column_stack([np.ones_like(x),x,v,x**3,x*v,x*x*v,v**p,x*v**q,x*x*v**r,x**s*v])
def res(pr):
    X=design(pr)
    c,*_=np.linalg.lstsq(X,dv_dt,rcond=None)
